def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_me, last_opp = history[-1]
    if n < 8:
        if opp[-1] == 'D' and opp[-2] == 'D':
            return 'D'
        return 'C'
    def od(k):
        k = min(k, n)
        return sum(1 for i in range(n - k, n) if opp[i] == 'D')
    def md(k):
        k = min(k, n)
        return sum(1 for i in range(n - k, n) if me[i] == 'D')
    total_opp_d = sum(1 for a in opp if a == 'D')
    total_me_d = sum(1 for a in me if a == 'D')
    recent_opp_def = od(12)
    recent_me_def = md(12)
    opp_coop = n - total_opp_d
    if n >= 92:
        if opp_coop * 2 >= n:
            if total_me_d < 3:
                return 'D'
            return 'D'
        if opp[-1] == 'D':
            return 'D'
        return 'C'
    if recent_opp_def >= 10:
        return 'D'
    if recent_opp_def == 0:
        if total_me_d == 0:
            if n % 9 == 0 and n < 85:
                return 'D'
            return 'C'
        if last_me == 'D' and n % 5 != 0:
            return 'C'
        return 'C'
    streak = 1
    for i in range(n - 1, 0, -1):
        if opp[i] == opp[i - 1]:
            streak += 1
        else:
            break
    if opp[-1] == 'D':
        if streak >= 3:
            if streak >= 6:
                return 'D'
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        if last_me == 'D':
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        if recent_opp_def >= 5:
            return 'D'
        return 'D'
    else:
        if last_me == 'D':
            if recent_me_def >= 5 and rng.random() < 0.4:
                return 'D'
            return 'C'
        if recent_opp_def >= 3:
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        if opp_coop * 4 >= n * 3:
            if total_me_d > total_opp_d + 2 and n < 90:
                if rng.random() < 0.3:
                    return 'D'
            return 'C'
        return 'C'
